fn new(version: usize, goal: &BattlePlanGoal, data: &OperationData, player: &PlayerState) -> DeathMatchBattle

// 747
let mut chats: Vec<Chat> = Vec::new();             // {cap=0, ptr=8(dangling), len=0}

// 749~751  — 이 함수의 유일한 분기
if goal.tag == 0 {                                  // BattlePlanGoal::TryKill(__0, __1)
    let target = goal.__0;                          // +0x8
    // 750: chats.push(Chat::Battle(target, 0))
    RawVec::<Chat>::grow_one(&mut chats);           // cap 0 이므로 실제 할당 발생
    let end = chats.ptr;
    end.tag = 3; end.__0 = target; end.__1 = 0;     // Chat::Battle(target, 0)
    chats.len = 1;
}
// 태그가 1/2/3 이면 chats 는 빈 Vec 그대로 (대사 없음)

// 753 — 구조체 리터럴 (필드별 초기값은 writes 표 참조)
let sub = BattlePlanGoal::base_sub_goal(goal, version, player, data);   // (i64, i64)

// 754
let tick = (*data.cache).game.vtable[+0x28](game.data_ptr);            // usize, '현재 틱' 추정

DeathMatchBattle {
    main_goal:  *goal,          // 0x0d0  인자 그대로 24B 복사
    sub_goal:   sub,            // 0x0e8 / 0x0f0
    chats,                      // 0x0f8  (755)
    start_tick: tick,           // 0x110
    flee_die:   i64::MAX,       // 0x118  센티널
    stance:     Commit,         // 0x176
    tactic:     Standard,       // 0x177
    scene:      Stand,          // 0x178
    scene_last_from: Stand,     // 0x179
    dive_tower: None,           // 0x17a (0xFF)
    main_objective: None,       // 0x17b (0xFF)
    // 그 외: Option 9개 = None(태그워드 0), bool 6개 = false,
    //        시간/누적 9필드(0x120~0x16f) = memset 0, lean_last_sign = 0
}

// ── 초기값의 출처 요약 (판단에 직결되는 부분) ──
// 외부에서 값을 '가져오는' 필드는 딱 4개다:
//   ① main_goal  ← 인자 goal 통째로 (판단의 최상위 목표가 그대로 박힌다)
//   ② sub_goal   ← base_sub_goal(goal, version, player, data) — 이 생성자의 유일한 판단 호출.
//                   version/player 가 여기로만 흘러가므로 '버전별·선수별 차이'는 전부 그 함수 안에 있다.
//   ③ chats      ← goal 이 TryKill 일 때만 Chat::Battle(target, 0) 1개
//   ④ start_tick ← data.cache.game 의 vtable 메서드(현재 틱 추정)
// 나머지 32개 필드는 전부 상수: None / false / 0 / Commit / Standard / Stand / i64::MAX.
// 즉 이 생성자는 '아무 이력도 없는 백지 상태'를 만들고, 실제 판단은 이후 tick 함수들이
// stance·scene·*_tick·*_basis 필드를 갱신하면서 수행한다.
